             [('Gallstones', 'Suspected gallstones, 35-year-old.', {'test': 'Ultrasound'}), ('Head injury', 'Head injury on anticoagulants with vomiting.', {'test': 'CT'}),
              ('Cord', 'Suspected spinal cord compression.', {'test': 'MRI'}), ('Wrist', 'Fall on outstretched hand, deformed wrist.', {'test': 'Plain X-ray'}), ('Pregnant RUQ', 'RUQ pain at 20 weeks of pregnancy.', {'test': 'Ultrasound'}, 'Avoid ionising radiation when an alternative exists.')],
             'Dr Anna Weiss, radiology registrar', 'Talk me through your requests.',
